#!/bin/sh
# PostgreSQL first-boot init script (mounted at /docker-entrypoint-initdb.d; runs only when the data volume is
# empty). Creates the TrellisKit system-of-record database and role and the RecallDB database and role, enables
# pgvector and pg_trgm in both (pg_trgm backs the library search indexes and RecallDB), and grants least-privilege rights. Passwords come from the
# environment (docker/.env.local, generated by env-local.sh), never from this file. docs/TRELLISKIT.md section 13.
#
# TrellisKit (the same rights as the AWS db-bootstrap container, ApiStack.BootstrapSql): the database is owned by
# the bootstrap superuser, not the application role. The role gets CONNECT and TEMPORARY, USAGE and CREATE on
# schema public (its migrations create and own the tables), the Verbex search schema (TK_SEARCH_SCHEMA, default
# search) created here and owned by the role, and CREATE on the database. CREATE on the database is only there
# because the server runs CREATE SCHEMA IF NOT EXISTS for the search schema on start, and PostgreSQL checks that
# privilege even when the schema exists; it allows creating schemas, never databases or roles.
#
# RecallDB owns its own database (it migrates its tables there); PUBLIC may connect to neither database.
set -eu

: "${TK_DB_NAME:=trelliskit}"
: "${TK_DB_USERNAME:=trelliskit}"
: "${TK_DB_PASSWORD:?TK_DB_PASSWORD is required}"
: "${TK_RECALLDB_DB_NAME:=recalldb}"
: "${TK_RECALLDB_DB_USERNAME:=recalldb}"
: "${TK_RECALLDB_DB_PASSWORD:?TK_RECALLDB_DB_PASSWORD is required}"
: "${TK_SEARCH_SCHEMA:=search}"

psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" \
  -v tk_db="$TK_DB_NAME" -v tk_user="$TK_DB_USERNAME" -v tk_password="$TK_DB_PASSWORD" -v tk_search="$TK_SEARCH_SCHEMA" \
  -v rd_db="$TK_RECALLDB_DB_NAME" -v rd_user="$TK_RECALLDB_DB_USERNAME" -v rd_password="$TK_RECALLDB_DB_PASSWORD" <<'SQL'
CREATE ROLE :"tk_user" LOGIN PASSWORD :'tk_password' NOSUPERUSER NOCREATEDB NOCREATEROLE;
CREATE ROLE :"rd_user" LOGIN PASSWORD :'rd_password' NOSUPERUSER NOCREATEDB NOCREATEROLE;
CREATE DATABASE :"tk_db";
CREATE DATABASE :"rd_db" OWNER :"rd_user";
REVOKE ALL ON DATABASE :"tk_db" FROM PUBLIC;
REVOKE ALL ON DATABASE :"rd_db" FROM PUBLIC;
GRANT CONNECT, TEMPORARY, CREATE ON DATABASE :"tk_db" TO :"tk_user";
GRANT CONNECT, TEMPORARY ON DATABASE :"rd_db" TO :"rd_user";
\connect :"tk_db"
CREATE EXTENSION IF NOT EXISTS vector SCHEMA public;
CREATE EXTENSION IF NOT EXISTS pg_trgm SCHEMA public;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
GRANT USAGE, CREATE ON SCHEMA public TO :"tk_user";
CREATE SCHEMA IF NOT EXISTS :"tk_search" AUTHORIZATION :"tk_user";
\connect :"rd_db"
CREATE EXTENSION IF NOT EXISTS vector SCHEMA public;
CREATE EXTENSION IF NOT EXISTS pg_trgm SCHEMA public;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
GRANT USAGE, CREATE ON SCHEMA public TO :"rd_user";
SQL

echo "trelliskit-postgres-init: created databases $TK_DB_NAME (search schema $TK_SEARCH_SCHEMA) and $TK_RECALLDB_DB_NAME with pgvector"
